.qa-accent-cards {
  --qa-primary: #0d9488;
  --qa-primary-dark: #0f766e;
  --qa-surface: #ffffff;
  --qa-border: #e2e8f0;
  --qa-text: #1e293b;
  --qa-text-secondary: #64748b;
  --qa-text-tertiary: #94a3b8;
  --qa-bg-subtle: #f8fafc;
  --qa-accent-warm: #f59e0b;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--qa-surface);
  border-radius: 6px;
  border: 1px solid var(--qa-border);
  padding: 16px;
  box-sizing: border-box;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.qa-indicator-band {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--qa-border);
  flex-shrink: 0;
}

.qa-indicator-left {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.qa-indicator-label {
  font-size: 12px;
  color: var(--qa-text-secondary);
  font-weight: 500;
}

.qa-indicator-value {
  font-size: 16px;
  font-weight: 700;
  color: var(--qa-text);
  letter-spacing: -0.02em;
}

.qa-indicator-right {
  display: flex;
  align-items: center;
}

.qa-indicator-badge {
  font-size: 11px;
  color: var(--qa-text-secondary);
  background: var(--qa-bg-subtle);
  padding: 4px 10px;
  border-radius: 4px;
  font-weight: 500;
}

.qa-indicator-badge em {
  font-style: normal;
  color: var(--qa-accent-warm);
  font-weight: 700;
  margin-left: 2px;
}

.qa-main-grid {
  display: flex;
  gap: 10px;
  flex: 1;
  min-height: 0;
}

.qa-primary-action {
  width: 42%;
  min-width: 120px;
  background: linear-gradient(135deg, var(--qa-primary) 0%, var(--qa-primary-dark) 100%);
  border-radius: 6px;
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  color: #fff;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.qa-primary-action:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(13, 148, 136, 0.25);
}

.qa-primary-action:active {
  transform: translateY(0);
}

.qa-primary-icon {
  opacity: 0.95;
}

.qa-primary-label {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.qa-primary-meta {
  font-size: 11px;
  opacity: 0.85;
  font-weight: 500;
}

.qa-primary-progress {
  margin-top: 4px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}

.qa-progress-track {
  width: 80%;
  height: 3px;
  background: rgba(255,255,255,0.2);
  border-radius: 2px;
  overflow: hidden;
}

.qa-progress-fill {
  height: 100%;
  background: rgba(255,255,255,0.9);
  border-radius: 2px;
  transition: width 0.3s ease;
}

.qa-progress-text {
  font-size: 9px;
  opacity: 0.7;
  font-weight: 500;
}

.qa-secondary-grid {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 8px;
  min-width: 0;
}

.qa-sec-card {
  background: var(--qa-surface);
  border: 1px solid var(--qa-border);
  border-radius: 6px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  cursor: pointer;
  transition: all 0.15s ease;
  color: var(--qa-primary);
}

.qa-sec-card:hover {
  border-color: var(--qa-primary);
  background: var(--qa-bg-subtle);
}

.qa-sec-card:active {
  transform: scale(0.98);
}

.qa-sec-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--qa-text);
}

.qa-sec-meta {
  font-size: 10px;
  color: var(--qa-text-tertiary);
  font-weight: 500;
}

.qa-bridge-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--qa-bg-subtle);
  border: 1px solid var(--qa-border);
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
  flex-shrink: 0;
}

.qa-bridge-bar:hover {
  border-color: var(--qa-primary);
  background: #f0fdfa;
}

.qa-bridge-icon {
  color: var(--qa-primary);
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.qa-bridge-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--qa-text);
  flex-shrink: 0;
}

.qa-bridge-meta {
  font-size: 11px;
  color: var(--qa-text-secondary);
  flex: 1;
  text-align: right;
  font-weight: 500;
}

.qa-bridge-arrow {
  font-size: 14px;
  color: var(--qa-text-tertiary);
  flex-shrink: 0;
}

@media (max-width: 480px) {
  .qa-accent-cards {
    padding: 12px;
    gap: 10px;
  }

  .qa-main-grid {
    flex-direction: column;
  }

  .qa-primary-action {
    width: 100%;
    min-width: auto;
    padding: 14px;
    flex-direction: row;
    justify-content: flex-start;
    gap: 12px;
  }

  .qa-primary-progress {
    margin-top: 0;
    margin-left: auto;
    width: auto;
    align-items: flex-end;
  }

  .qa-progress-track {
    width: 60px;
  }

  .qa-secondary-grid {
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: 1fr;
  }

  .qa-sec-card {
    padding: 10px 4px;
  }

  .qa-sec-meta {
    display: none;
  }
}

