.ob-mpath {
  --ob-blue: #2563eb;
  --ob-blue-soft: #dbeafe;
  --ob-green: #059669;
  --ob-green-soft: #d1fae5;
  --ob-amber: #d97706;
  --ob-amber-soft: #fef3c7;
  --ob-gray: #9ca3af;
  --ob-gray-soft: #f3f4f6;
  --ob-text: #111827;
  --ob-text-secondary: #6b7280;
  --ob-text-tertiary: #9ca3af;
  --ob-border: #e5e7eb;
  --ob-surface: #ffffff;
  --ob-radius: 6px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--ob-surface);
  border: 1px solid var(--ob-border);
  border-radius: var(--ob-radius);
  padding: 20px 24px;
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ob-mpath__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
}

.ob-mpath__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ob-text);
  margin: 0;
  line-height: 1.4;
}

.ob-mpath__count {
  font-size: 13px;
  font-weight: 500;
  color: var(--ob-text-secondary);
  background: var(--ob-gray-soft);
  padding: 3px 10px;
  border-radius: 12px;
  line-height: 1;
}

.ob-mpath__body {
  display: flex;
  gap: 24px;
  flex: 1;
  min-height: 0;
}

.ob-mpath__rail {
  display: flex;
  flex-direction: column;
  width: 156px;
  flex-shrink: 0;
  padding-top: 2px;
}

.ob-mpath__step {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.ob-mpath__node {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
}

.ob-mpath__node--pulse {
  position: relative;
}

.ob-mpath__node--pulse::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid var(--ob-blue);
  opacity: 0.35;
  animation: ob-mpath-pulse 2s ease-in-out infinite;
}

@keyframes ob-mpath-pulse {
  0%, 100% { transform: scale(1); opacity: 0.35; }
  50% { transform: scale(1.08); opacity: 0.15; }
}

.ob-mpath__step--done .ob-mpath__node {
  background: var(--ob-green-soft);
  color: var(--ob-green);
}

.ob-mpath__step--current .ob-mpath__node {
  background: var(--ob-blue-soft);
  color: var(--ob-blue);
}

.ob-mpath__step--pending .ob-mpath__node {
  background: var(--ob-gray-soft);
  color: var(--ob-gray);
  border: 1.5px dashed var(--ob-gray);
}

.ob-mpath__info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-top: 4px;
}

.ob-mpath__label {
  font-size: 13px;
  font-weight: 500;
  color: var(--ob-text);
  line-height: 1.3;
}

.ob-mpath__badge {
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 10px;
  line-height: 1.3;
  width: fit-content;
}

.ob-mpath__badge--done {
  background: var(--ob-green-soft);
  color: var(--ob-green);
}

.ob-mpath__badge--current {
  background: var(--ob-blue-soft);
  color: var(--ob-blue);
}

.ob-mpath__badge--pending {
  background: var(--ob-gray-soft);
  color: var(--ob-text-tertiary);
}

.ob-mpath__connector {
  width: 2px;
  height: 20px;
  margin-left: 13px;
  flex-shrink: 0;
}

.ob-mpath__connector--active {
  background: var(--ob-blue);
  opacity: 0.35;
}

.ob-mpath__connector--pending {
  background: var(--ob-gray);
  opacity: 0.2;
  border-left: 1.5px dashed var(--ob-gray);
  background: transparent;
  width: 0;
}

.ob-mpath__focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 0;
  border-left: 1px solid var(--ob-border);
  padding-left: 24px;
}

.ob-mpath__focus-head {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ob-mpath__focus-tag {
  font-size: 12px;
  font-weight: 600;
  color: var(--ob-blue);
  text-transform: none;
  letter-spacing: 0;
  line-height: 1.3;
}

.ob-mpath__focus-hint {
  font-size: 13px;
  color: var(--ob-text-secondary);
  line-height: 1.4;
}

.ob-mpath__focus-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ob-mpath__config-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.ob-mpath__config-key {
  font-size: 12px;
  color: var(--ob-text-tertiary);
  line-height: 1.3;
}

.ob-mpath__config-val {
  font-size: 12px;
  font-weight: 500;
  color: var(--ob-text);
  line-height: 1.3;
}

.ob-mpath__dock {
  display: flex;
  gap: 10px;
  margin-top: auto;
  padding-top: 4px;
}

.ob-mpath__btn {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--ob-radius);
  border: none;
  cursor: pointer;
  line-height: 1.3;
  white-space: nowrap;
  transition: opacity 0.15s ease;
}

.ob-mpath__btn:hover {
  opacity: 0.9;
}

.ob-mpath__btn--primary {
  background: var(--ob-blue);
  color: #fff;
  flex: 1;
  min-width: 0;
}

.ob-mpath__btn--secondary {
  background: var(--ob-gray-soft);
  color: var(--ob-text-secondary);
  border: 1px solid var(--ob-border);
  flex-shrink: 0;
}

@media (max-width: 640px) {
  .ob-mpath {
    padding: 16px;
    gap: 14px;
  }

  .ob-mpath__body {
    flex-direction: column;
    gap: 18px;
  }

  .ob-mpath__rail {
    width: 100%;
    flex-direction: row;
    align-items: flex-start;
    padding-top: 0;
  }

  .ob-mpath__step {
    flex: 1;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 8px;
  }

  .ob-mpath__info {
    align-items: center;
    padding-top: 0;
  }

  .ob-mpath__connector {
    width: 24px;
    height: 2px;
    margin: 14px 0 0 0;
    flex-shrink: 0;
    align-self: flex-start;
    margin-top: 14px;
  }

  .ob-mpath__connector--pending {
    border-left: none;
    border-top: 1.5px dashed var(--ob-gray);
    width: 24px;
    height: 0;
  }

  .ob-mpath__focus {
    border-left: none;
    padding-left: 0;
    border-top: 1px solid var(--ob-border);
    padding-top: 16px;
  }

  .ob-mpath__dock {
    flex-direction: column;
  }

  .ob-mpath__btn--secondary {
    width: 100%;
  }
}

