.ob-mpath {
  --ob-done: #0d9488;
  --ob-current: #2563eb;
  --ob-pending: #94a3b8;
  --ob-surface: #f8fafc;
  --ob-border: #e2e8f0;
  --ob-text: #0f172a;
  --ob-muted: #64748b;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #fff;
  border: 1px solid var(--ob-border);
  border-radius: 6px;
  padding: 20px 24px;
  height: 100%;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.ob-mpath__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 16px;
  flex-shrink: 0;
}

.ob-mpath__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ob-text);
  margin: 0;
  line-height: 1.3;
}

.ob-mpath__counter {
  font-size: 13px;
  font-weight: 500;
  color: var(--ob-current);
  background: #eff6ff;
  padding: 2px 10px;
  border-radius: 12px;
  line-height: 1;
}

.ob-mpath__track {
  display: flex;
  align-items: stretch;
  flex: 1;
  min-height: 0;
  gap: 0;
}

.ob-mpath__step {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  padding: 12px 8px;
  border-radius: 6px;
  transition: background 0.15s ease;
}

.ob-mpath__step--done {
  background: #f0fdfa;
}

.ob-mpath__step--current {
  background: #fff;
  box-shadow: inset 0 0 0 1.5px var(--ob-current);
}

.ob-mpath__step--pending {
  background: var(--ob-surface);
}

.ob-mpath__badge {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  flex-shrink: 0;
}

.ob-mpath__step--done .ob-mpath__badge {
  background: var(--ob-done);
  color: #fff;
}

.ob-mpath__step--current .ob-mpath__badge {
  background: var(--ob-current);
  color: #fff;
}

.ob-mpath__step--pending .ob-mpath__badge {
  background: #fff;
  color: var(--ob-pending);
  border: 1.5px dashed var(--ob-pending);
  box-sizing: border-box;
}

.ob-mpath__badge--pulse {
  position: relative;
}

.ob-mpath__badge--pulse::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  border: 2px solid var(--ob-current);
  opacity: 0;
  animation: ob-pulse 2s ease-out infinite;
}

@keyframes ob-pulse {
  0% { transform: scale(1); opacity: 0.5; }
  100% { transform: scale(1.35); opacity: 0; }
}

.ob-mpath__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ob-mpath__label {
  font-size: 13px;
  font-weight: 500;
  color: var(--ob-text);
  line-height: 1.35;
  white-space: nowrap;
}

.ob-mpath__status {
  font-size: 11px;
  font-weight: 400;
  line-height: 1.35;
}

.ob-mpath__step--done .ob-mpath__status {
  color: var(--ob-done);
}

.ob-mpath__step--current .ob-mpath__status {
  color: var(--ob-current);
}

.ob-mpath__step--pending .ob-mpath__status {
  color: var(--ob-pending);
}

.ob-mpath__connector {
  position: absolute;
  top: 28px;
  right: -50%;
  width: calc(100% - 32px);
  height: 2px;
  background: var(--ob-done);
  z-index: 0;
  transform: translateX(-50%);
}

.ob-mpath__connector--dashed {
  background: transparent;
  border-top: 2px dashed var(--ob-border);
}

.ob-mpath__step:last-child .ob-mpath__connector {
  display: none;
}

.ob-mpath__action {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--ob-border);
  flex-shrink: 0;
}

.ob-mpath__cta {
  flex: 1;
  height: 36px;
  border-radius: 6px;
  border: none;
  background: var(--ob-current);
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease;
  white-space: nowrap;
}

.ob-mpath__cta:hover {
  background: #1d4ed8;
}

.ob-mpath__secondary {
  height: 36px;
  padding: 0 16px;
  border-radius: 6px;
  border: 1px solid var(--ob-border);
  background: #fff;
  color: var(--ob-muted);
  font-size: 13px;
  font-weight: 400;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.ob-mpath__secondary:hover {
  border-color: var(--ob-current);
  color: var(--ob-current);
}

@media (max-width: 640px) {
  .ob-mpath__track {
    flex-direction: column;
    gap: 8px;
  }

  .ob-mpath__step {
    flex-direction: row;
    align-items: center;
    text-align: left;
    padding: 14px 16px;
  }

  .ob-mpath__badge {
    margin-bottom: 0;
    margin-right: 14px;
  }

  .ob-mpath__connector {
    display: none;
  }

  .ob-mpath__action {
    flex-direction: column;
  }

  .ob-mpath__secondary {
    width: 100%;
  }
}

