  --ta-primary: var(--home-primary, #0d9488);
  --ta-primary-hover: #0f766e;
  --ta-text: var(--home-text, #1e293b);
  --ta-text-secondary: #64748b;
  --ta-text-tertiary: #94a3b8;
  --ta-border: var(--home-border, #e2e8f0);
  --ta-radius: var(--home-radius-sm, 6px);
  --ta-live: #0d9488;
  --ta-live-bg: #f0fdfa;
  --ta-demo: #6366f1;
  --ta-demo-bg: #eef2ff;
  --ta-safe: #10b981;
  --ta-warn: #f59e0b;
  --ta-danger: #ef4444;

  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--ta-card);
  border: 1px solid var(--ta-border);
  border-radius: var(--ta-radius);
  overflow: hidden;
}

.ai-html-ta-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--ta-border);
  flex-shrink: 0;
}

.ai-html-ta-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ta-text);
  margin: 0;
  line-height: 1.4;
}

.ai-html-ta-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.ai-html-ta-badge {
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 4px;
  line-height: 1.5;
}

.ai-html-ta-live {
  background: var(--ta-live-bg);
  color: var(--ta-live);
}

.ai-html-ta-demo {
  background: var(--ta-demo-bg);
  color: var(--ta-demo);
}

.ai-html-ta-divider {
  width: 1px;
  height: 14px;
  background: var(--ta-border);
}

.ai-html-ta-equity {
  font-size: 12px;
  color: var(--ta-text-secondary);
}

.ai-html-ta-equity strong {
  color: var(--ta-text);
  font-weight: 600;
  margin-left: 4px;
}

.ai-html-ta-body {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.ai-html-ta-col {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.ai-html-ta-col:first-child {
  border-right: 1px solid var(--ta-border);
}

.ai-html-ta-colhead {
  padding: 10px 16px;
  border-bottom: 1px solid var(--ta-border);
  flex-shrink: 0;
}

.ai-html-ta-tag {
  font-size: 12px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 4px;
  display: inline-block;
}

.ai-html-ta-tag-live {
  background: var(--ta-live-bg);
  color: var(--ta-live);
}

.ai-html-ta-tag-demo {
  background: var(--ta-demo-bg);
  color: var(--ta-demo);
}

.ai-html-ta-list {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
}

.ai-html-ta-row {
  padding: 14px 16px;
  border-bottom: 1px solid var(--ta-border);
}

.ai-html-ta-row:last-child {
  border-bottom: none;
}

.ai-html-ta-rowtop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.ai-html-ta-env {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--ta-text-secondary);
}

.ai-html-ta-kind {
  font-weight: 600;
  color: var(--ta-live);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.ai-html-ta-kind-demo {
  color: var(--ta-demo);
}

.ai-html-ta-sep {
  color: var(--ta-text-tertiary);
}

.ai-html-ta-acct {
  font-size: 13px;
  font-weight: 600;
  color: var(--ta-text);
  font-family: 'SF Mono', monospace;
  letter-spacing: 0.3px;
}

.ai-html-ta-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px 12px;
  margin-bottom: 12px;
}

.ai-html-ta-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ai-html-ta-label {
  font-size: 11px;
  color: var(--ta-text-tertiary);
  line-height: 1.4;
}

.ai-html-ta-value {
  font-size: 12px;
  font-weight: 500;
  color: var(--ta-text);
  line-height: 1.4;
}

.ai-html-ta-margin {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ai-html-ta-ratio {
  font-size: 12px;
  font-weight: 600;
  color: var(--ta-safe);
}

.ai-html-ta-bar {
  width: 100%;
  height: 3px;
  background: #e2e8f0;
  border-radius: 2px;
  overflow: hidden;
}

.ai-html-ta-barfill {
  height: 100%;
  border-radius: 2px;
  transition: width 0.3s ease;
}

.ai-html-ta-safe {
  background: var(--ta-safe);
}

.ai-html-ta-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.ai-html-ta-btn {
  font-size: 12px;
  font-weight: 500;
  padding: 5px 14px;
  border-radius: var(--ta-radius);
  border: 1px solid transparent;
  cursor: pointer;
  line-height: 1.5;
  transition: all 0.15s ease;
}

.ai-html-ta-btn-primary {
  background: var(--ta-primary);
  color: #fff;
  border-color: var(--ta-primary);
}

.ai-html-ta-btn-primary:hover {
  background: var(--ta-primary-hover);
  border-color: var(--ta-primary-hover);
}

.ai-html-ta-btn-secondary {
  background: var(--ta-card);
  color: var(--ta-text);
  border-color: var(--ta-border);
}

.ai-html-ta-btn-secondary:hover {
  background: var(--ta-bg);
}

.ai-html-ta-btn-ghost {
  background: transparent;
  color: var(--ta-text-secondary);
  border-color: var(--ta-border);
}

.ai-html-ta-btn-ghost:hover {
  background: var(--ta-bg);
  color: var(--ta-text);
}

@media (max-width: 640px) {
  .ai-html-ta-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .ai-html-ta-body {
    flex-direction: column;
    overflow-y: auto;
  }

  .ai-html-ta-col:first-child {
    border-right: none;
    border-bottom: 1px solid var(--ta-border);
  }

  .ai-html-ta-metrics {
    grid-template-columns: repeat(2, 1fr);
  }

  .ai-html-ta-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 480px) {
  .ai-html-ta-metrics {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
  }

  .ai-html-ta-row {
    padding: 12px;
  }

  .ai-html-ta-btn {
    padding: 5px 12px;
    font-size: 11px;
  }
}

